<?php
declare(strict_types=1);namespace App\Http\Requests\Finance;use Illuminate\Foundation\Http\FormRequest;class SppRequest extends FormRequest{public function authorize():bool{return $this->user()?->can('finance.invoice.create')??false;}public function rules():array{return ['academic_year_id'=>'required|exists:academic_years,id','semester_id'=>'required|exists:semesters,id','billing_month'=>'required|date_format:Y-m','classroom_id'=>'nullable|exists:classrooms,id','fee_type_id'=>'required|exists:fee_types,id','amount'=>'required|integer|min:1|max:999999999999','due_date'=>'required|date'];}}
